const T = 2;
const RANGES = { s1: [0, 100], s2: [-20, 80], s3: [2, 400] };

const text = String(msg.payload).replace(/^\uFEFF/, '');
const sql = [];

text.split(/\r?\n/).forEach(raw => {
    const line = raw.trim();
    if (!line) return;

    const parts = line.split(' ');
    const kind = parts[0];
    const f = {};

    parts.slice(1).forEach(p => {
        const kv = p.split('=');
        f[kv[0]] = kv[1];
    });

    const n = parseInt(f.n);
    if (isNaN(n)) return;
    const t = n * T;

    if (kind === 'DATA') {
        ['s1', 's2', 's3'].forEach(s => {
            const v = parseFloat(f[s]);
            if (isNaN(v)) return;

            sql.push(`INSERT INTO readings(n,t_s,sensor,value) VALUES(${n},${t},'${s}',${v});`);

            const min = RANGES[s][0];
            const max = RANGES[s][1];
            if (v < min || v > max) {
                sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'FAULT','датчик ${s} вне диапазона');`);
            }
        });
    } else if (kind === 'EVENT') {
        if (f.type === 'THRESHOLD' || f.type === 'NORMAL') {
            sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'${f.type}','');`);
        }
    }
});

const head = 'BEGIN;\nDELETE FROM readings;\nDELETE FROM events;\n' + "DELETE FROM sqlite_sequence WHERE name IN ('readings','events');\n";
return [null, { payload: head + sql.join('\n') + '\nCOMMIT;\n' }];
